# WARNING: DO NOT EDIT THIS FILE DIRECTLY.
# This file is a child copy that shadows or shares code with the Tools repository.
# Canonical changes must be made in the Tools repository under src/shared/python/
# and synchronized back to UpstreamDrift. Direct edits here risk being lost.

from __future__ import annotations

from pathlib import Path
import pytest

SHARED_PATHS = [
    "ai",
    "calc_backend",
    "chat",
    "codemap",
    "contracts.py",
    "cors.py",
    "data_processing",
    "data_processor",
    "deprecation.py",
    "file_watcher",
    "gui_launcher",
    "humanoid_character_builder",
    "logging_pkg",
    "model_generation",
    "notes",
    "plot_engine",
    "plot_theme",
    "programmatic_pid",
    "reporting",
    "rotation_transforms",
    "safe_eval.py",
    "safe_pandas_eval.py",
    "scripting",
    "sidekick",
    "signal_toolkit",
    "theme",
    "ui",
    "upstream_drift_tools",
]


@pytest.mark.unit
def test_all_shared_files_have_warning_header() -> None:
    """Assert that all shared/shadowed Python files in UD contain the warning header.

    This ensures that developers and AI agents do not modify child files in UpstreamDrift
    directly without editing their canonical sources in the Tools repository.
    """
    root = Path(__file__).resolve().parents[3]
    ud_shared_root = root / "src" / "shared" / "python"

    unflagged: list[str] = []
    for name in SHARED_PATHS:
        p = ud_shared_root / name
        if p.is_file() and p.suffix == ".py":
            _check_file(p, unflagged, ud_shared_root)
        elif p.is_dir():
            for file_p in p.rglob("*.py"):
                if "__pycache__" in file_p.parts:
                    continue
                _check_file(file_p, unflagged, ud_shared_root)

    assert not unflagged, (
        "Found shared/shadowed files that lack the protective warning header. "
        "These files shadow or share code with the Tools repository, and edits "
        "must be made in the Tools repository first.\n\n"
        "Unflagged files:\n" + "\n".join(unflagged)
    )


def _check_file(file_path: Path, unflagged: list[str], root: Path) -> None:
    try:
        content = file_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return
    if "WARNING: DO NOT EDIT THIS FILE DIRECTLY" not in content:
        unflagged.append(str(file_path.relative_to(root)))
